// Generated by /ship coverage audit (Claude) — 2026-10-16
// Value: protects=/grading-credits renders the list (in-frame empty state) for zero credits, passes view_all, sessions.view, today and the same limit the RPC was asked for;
// fails_when=the bare page EmptyState returns for zero rows, the list limit differs from p_limit (a cut total reads exact), a flag is dropped, today is the UTC date, or the shared loader stops defaulting to 200 rows for other callers (the dashboard summary);
// why_new=step 14a drops the route's empty branch and adds these props; seam=none; no_claim=does not prove the RPC orders newest first or honours p_limit
import type { ComponentProps, ReactElement } from "react";
import { afterEach, describe, expect, it, vi } from "vitest";

import GradingCreditsRoute from "@/app/(app)/grading-credits/page";
import { getGradingCreditsDashboardResult } from "@/features/grading-credits/data";
import type { GradingCreditListPage } from "@/features/grading-credits/grading-credit-list-page";

const dependencies = vi.hoisted(() => ({
  getCachedDatabasePermissions: vi.fn(),
  GradingCreditListPage: vi.fn(() => null),
  rpc: vi.fn(),
}));

vi.mock("@/lib/permissions/database-permissions", () => ({
  getCachedDatabasePermissions: dependencies.getCachedDatabasePermissions,
}));
vi.mock("@/lib/supabase/server", () => ({ createSupabaseServerClient: vi.fn(async () => ({ rpc: dependencies.rpc })) }));
vi.mock("@/features/grading-credits/grading-credit-list-page", () => ({
  GradingCreditListPage: dependencies.GradingCreditListPage,
}));

type ListElement = ReactElement<ComponentProps<typeof GradingCreditListPage>>;

async function renderRoute(permissions: string[], rows: unknown[] = []) {
  dependencies.getCachedDatabasePermissions.mockResolvedValue({ ok: true, permissions });
  dependencies.rpc.mockResolvedValue({ data: rows, error: null });
  return (await GradingCreditsRoute()) as ListElement;
}

afterEach(() => {
  vi.clearAllMocks();
  vi.useRealTimers();
});

describe("Grading credits route (step 14a wiring)", () => {
  it("renders the list page, not a bare page empty state, when no credit was loaded", async () => {
    const element = await renderRoute(["grading_credits.view"]);
    expect(element.type).toBe(dependencies.GradingCreditListPage);
    expect(element.props.entries).toEqual([]);
    expect(element.props).toMatchObject({ canViewAll: false, canViewSessions: false });
  });

  it("tells the list the same row limit the RPC was asked for, so a full page reads as a lower bound", async () => {
    const element = await renderRoute(["grading_credits.view", "grading_credits.view_all", "sessions.view"], [
      {
        class_code: "7A",
        class_name: "Toán 7A",
        class_session_id: "s-1",
        credit_units: 1,
        credited_at: "2026-09-30T17:30:00Z",
        grader_display_name: "Cô Lan",
        grader_id: "g-1",
        grading_credit_id: "c-1",
        session_date: "2026-10-01",
        session_result_id: "r-1",
        student_full_name: "Nguyễn An",
        student_id: "st-1",
        student_public_code: "HS001",
      },
    ]);
    expect(dependencies.rpc).toHaveBeenCalledWith("get_grading_credits_dashboard", { p_limit: 500 });
    expect(element.props.limit).toBe(500);
    expect(element.props).toMatchObject({ canViewAll: true, canViewSessions: true });
    expect(element.props.entries).toEqual([expect.objectContaining({ classSessionId: "s-1", creditedAt: "2026-09-30T17:30:00Z", id: "c-1" })]);
  });

  it("keeps the shared loader at 200 rows unless a caller asks for more (dashboard summary), and passes an explicit limit through", async () => {
    dependencies.rpc.mockResolvedValue({ data: [], error: null });

    await getGradingCreditsDashboardResult();
    expect(dependencies.rpc).toHaveBeenLastCalledWith("get_grading_credits_dashboard", { p_limit: 200 });

    await getGradingCreditsDashboardResult(500);
    expect(dependencies.rpc).toHaveBeenLastCalledWith("get_grading_credits_dashboard", { p_limit: 500 });
  });

  it("defaults the month from the Vietnam business date", async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
    // 17:30 UTC on 30/09 is already 1 October in Vietnam.
    vi.setSystemTime(new Date("2026-09-30T17:30:00Z"));
    const element = await renderRoute(["grading_credits.view"]);
    expect(element.props.today).toBe("2026-10-01");
  });
});
